      if (age <= entry.ttl) {
        count++;
      }
    } else if (this.ttl !== null) {
      const age = this.now() - entry.timestamp;
      if (age <= this.ttl) {
        count++;
      }
    } else {
      count++;
    }
  }
  return count;
}

keys() {
